<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { request } from '../../services/api'
const dishes=ref([]), category=ref('全部'), active=ref({}), note=ref(''), tableNo=ref('A08'), remark=ref(''), orders=ref([]), loading=ref(true)
const cats=['全部','主食','小食','饮品'];const filtered=computed(()=>dishes.value.filter(x=>category.value==='全部'||x.category===category.value));const count=computed(()=>Object.values(active.value).reduce((a,b)=>a+b,0));const total=computed(()=>dishes.value.reduce((sum,d)=>sum+(active.value[d.id]||0)*d.price,0))
async function load(){try{dishes.value=await request('/api/dishes');orders.value=await request(`/api/orders?tableNo=${tableNo.value}`)}catch(e){note.value=e.message||'服务暂不可用'}finally{loading.value=false}}
function add(d){active.value={...active.value,[d.id]:(active.value[d.id]||0)+1};uni.showToast({title:'已加入餐篮',icon:'success'})}function minus(d){const n=Math.max(0,(active.value[d.id]||0)-1);active.value={...active.value,[d.id]:n}}
async function submit(){try{const items=Object.entries(active.value).filter(([,q])=>q>0).map(([dishId,quantity])=>({dishId:Number(dishId),quantity}));if(!items.length)throw Error('请先选择菜品');const result=await request('/api/orders','POST',{tableNo:tableNo.value,note:remark.value,items});orders.value=[result,...orders.value];active.value={};note.value=`下单成功，订单 #${result.id} 已提交后厨`;uni.showToast({title:'下单成功',icon:'success'})}catch(e){note.value=e.message||'下单失败'}}
onLoad(load)
</script>
<template><view class="page"><view class="hero"><view><text class="eyebrow">TABLE SERVICE · {{tableNo}}</text><text class="title">这一餐，慢慢吃</text><text class="subtitle">扫码即点 · 少等一会儿 · 现做更好吃</text></view><text class="hero-icon">🍱</text></view><view class="table-row"><text>桌号</text><input v-model="tableNo" maxlength="12" @blur="load"/><text class="table-edit">可修改</text></view><scroll-view scroll-x class="cats"><text v-for="c in cats" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</text></scroll-view><view v-if="loading" class="empty">正在加载菜单...</view><view v-else class="menu"><view v-for="d in filtered" :key="d.id" class="dish"><view class="dish-icon">{{d.icon}}<text v-if="d.badge" class="badge">{{d.badge}}</text></view><view class="dish-info"><text class="dish-name">{{d.name}}</text><text class="dish-desc">{{d.desc}}</text><view class="dish-bottom"><text class="price">¥{{d.price}}</text><view class="stepper"><button @click="minus(d)" :disabled="!active[d.id]">−</button><text>{{active[d.id]||0}}</text><button @click="add(d)">＋</button></view></view></view></view></view><view class="order-section"><view class="section-head"><text class="section-title">备注</text><text class="section-tip">口味和餐具需求</text></view><input v-model="remark" class="remark" placeholder="例如：少辣、不要香菜、需要餐具"/><view class="section-head orders-title"><text class="section-title">本桌订单</text><text class="section-tip">后厨制作进度</text></view><view v-for="o in orders" :key="o.id" class="order"><view><text class="order-id">订单 #{{o.id}} · ¥{{o.total}}</text><text class="order-detail">{{o.items.map(x=>x.name+'×'+x.quantity).join('、')}}</text></view><text class="status">{{o.status}}</text></view><view v-if="!orders.length" class="empty">还没有提交过订单</view></view><view class="bottom"><view><text class="bottom-count">{{count}} 件</text><text class="bottom-total">合计 ¥{{total}}</text></view><button @click="submit" :disabled="!count">提交订单</button></view><view v-if="note" class="toast">{{note}}</view></view></template>
<style scoped>.page{min-height:100vh;background:#f7f7f6;padding-bottom:150rpx}.hero{padding:48rpx 30rpx 42rpx;background:linear-gradient(135deg,#792d27,#c46d47);color:#fff;display:flex;justify-content:space-between;align-items:center}.eyebrow{display:block;font-size:20rpx;letter-spacing:2rpx;opacity:.75}.title{display:block;font-size:47rpx;font-weight:bold;margin-top:20rpx}.subtitle{display:block;font-size:23rpx;opacity:.85;margin-top:12rpx}.hero-icon{font-size:106rpx}.table-row{height:84rpx;background:#fff;display:flex;align-items:center;padding:0 28rpx;gap:16rpx;font-size:24rpx}.table-row input{width:150rpx;background:#f5f5f4;padding:10rpx 14rpx;font-weight:bold}.table-edit{color:#a1a59e;font-size:20rpx}.cats{background:#fff;height:82rpx;white-space:nowrap}.cats text{display:inline-flex;height:82rpx;align-items:center;padding:0 30rpx;color:#777;font-size:25rpx}.cats text.active{color:#9e3e32;font-weight:bold;border-bottom:4rpx solid #9e3e32}.menu{padding:20rpx 24rpx}.dish{display:flex;background:#fff;margin-bottom:16rpx;padding:18rpx;gap:20rpx}.dish-icon{width:190rpx;height:190rpx;background:#f4e5d6;display:flex;align-items:center;justify-content:center;font-size:88rpx;position:relative;flex-shrink:0}.dish:nth-child(2n) .dish-icon{background:#e4eee8}.badge{position:absolute;left:10rpx;top:10rpx;background:#9e3e32;color:#fff;font-size:18rpx;padding:4rpx 10rpx}.dish-info{flex:1;display:flex;flex-direction:column}.dish-name{font-size:29rpx;font-weight:bold}.dish-desc{font-size:20rpx;color:#999;margin-top:12rpx}.dish-bottom{margin-top:auto;display:flex;align-items:center;justify-content:space-between}.price{font-size:30rpx;color:#a13e31;font-weight:bold}.stepper{display:flex;align-items:center;gap:12rpx}.stepper button{width:48rpx;height:48rpx;padding:0;line-height:44rpx;border:1rpx solid #d5d9d3;background:#fff;font-size:28rpx}.stepper text{min-width:20rpx;text-align:center;font-size:22rpx}.order-section{padding:0 24rpx}.section-head{display:flex;justify-content:space-between;align-items:center;margin:18rpx 0}.section-title{font-size:30rpx;font-weight:bold}.section-tip{font-size:20rpx;color:#999}.remark{height:76rpx;background:#fff;padding:0 20rpx;font-size:22rpx}.orders-title{margin-top:28rpx}.order{background:#fff;padding:20rpx;display:flex;justify-content:space-between;border-bottom:1rpx solid #f1f1ef}.order-id,.order-detail{display:block}.order-id{font-size:23rpx;font-weight:bold}.order-detail{font-size:20rpx;color:#999;margin-top:10rpx;max-width:500rpx}.status{color:#a13e31;font-size:20rpx}.empty{text-align:center;color:#999;padding:44rpx}.bottom{position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1rpx solid #eee;padding:16rpx 22rpx;display:flex;align-items:center;justify-content:space-between;z-index:5}.bottom-count,.bottom-total{display:block}.bottom-count{font-size:19rpx;color:#999}.bottom-total{font-size:31rpx;color:#a13e31;font-weight:bold}.bottom button{background:#9e3e32;color:#fff;border:0;padding:0 35rpx;height:72rpx;line-height:72rpx;font-size:25rpx}.bottom button[disabled]{opacity:.45}.toast{position:fixed;bottom:110rpx;left:24rpx;right:24rpx;background:#42302b;color:#fff;padding:20rpx;text-align:center;font-size:22rpx;z-index:7}</style>
